1	import type { Item } from "./insured-item.js";
2	import { insuranceValue } from "./price-list.js";
3	
4	export interface Damage {
5	  itemType: string;
6	  amount: number;
7	}
8	
9	export interface Incident {
10	  cause: string;
11	  damages: Damage[];
12	}
13	
14	export interface Policy {
15	  insuredItems: Item[];
16	  // Absent on a newly opened policy, which may still draw its whole cap.
17	  remainingCap?: number;
18	}
19	
20	export interface ClaimResult {
21	  payout: number;
22	  remainingCap: number;
23	  // The policy as it stands after this claim, for settling the next one.
24	  policy: Policy;
25	}
26	
27	const DEDUCTIBLE_PER_DAMAGE = 100;
28	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
29	
30	// The MHPCO insures a policy for the sum of its items' insurance values and
31	// pays out at most twice that sum over the policy's lifetime.
32	function insuranceSum(policy: Policy): number {
33	  return policy.insuredItems
34	    .map(insuranceValue)
35	    .reduce((sum, value) => sum + value, 0);
36	}
37	
38	function payoutCap(policy: Policy): number {
39	  return insuranceSum(policy) * CAP_MULTIPLE_OF_INSURANCE_SUM;
40	}
41	
42	function capAvailableFor(policy: Policy): number {
43	  return policy.remainingCap ?? payoutCap(policy);
44	}
45	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
46	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
47	const FULL_REIMBURSEMENT_RATE = 1;
48	
49	function damagedItem(policy: Policy, damage: Damage): Item | undefined {
50	  return policy.insuredItems.find((item) => item.type === damage.itemType);
51	}
52	
53	function isHighlyEnchanted(item: Item): boolean {
54	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
55	}
56	
57	// Which reimbursement clause covers the damaged item. Damage to a highly
58	// enchanted item is reimbursed at half; all other damage in full.
59	// The dragon-material clause is subsumed by that default: it reimburses in
60	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
61	// it never changes a payout and needs no branch of its own.
62	// An item the policy does not list has no clause and is reimbursed in full --
63	// rejecting such a damage entry is a separate, not yet implemented rule.
64	function reimbursementRateFor(item: Item | undefined): number {
65	  if (item !== undefined && isHighlyEnchanted(item)) {
66	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
67	  }
68	  return FULL_REIMBURSEMENT_RATE;
69	}
70	
71	// The MHPCO settles each damage event separately: it reimburses the damage
72	// under the applicable clause, then withholds its deductible once per event.
73	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
74	  const rate = reimbursementRateFor(damagedItem(policy, damage));
75	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
76	}
77	
78	export function claim(policy: Policy, incident: Incident): ClaimResult {
79	  const cap = capAvailableFor(policy);
80	  const settled = incident.damages
81	    .map((damage) => settlementForDamageEvent(policy, damage))
82	    .reduce((sum, amount) => sum + amount, 0);
83	  const payout = Math.min(settled, cap);
84	  const remainingCap = cap - payout;
85	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
86	}
