1	import type { Customer, Item } from "./insured-item.js";
2	import {
3	  COMPONENT_BASE_PREMIUM,
4	  isComponent,
5	  itemBasePremium,
6	} from "./price-list.js";
7	
8	const PROCESSING_FEE = 5;
9	const CURSE_SURCHARGE_RATE = 0.5;
10	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
11	const HIGH_ENCHANTMENT_LEVEL = 5;
12	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
13	const LOYALTY_DISCOUNT_RATE = 0.2;
14	const LOYALTY_YEARS = 2;
15	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
16	
17	const BLOCK_SIZE = 3;
18	const BLOCK_BASE_PREMIUM = 60;
19	
20	function alikeComponentGroupSizes(components: Item[]): number[] {
21	  const sizePerType = new Map<string, number>();
22	  for (const component of components) {
23	    sizePerType.set(component.type, (sizePerType.get(component.type) ?? 0) + 1);
24	  }
25	  return [...sizePerType.values()];
26	}
27	
28	function alikeComponentGroupBasePremium(groupSize: number): number {
29	  return groupSize === BLOCK_SIZE
30	    ? BLOCK_BASE_PREMIUM
31	    : groupSize * COMPONENT_BASE_PREMIUM;
32	}
33	
34	function componentsBasePremium(components: Item[]): number {
35	  return alikeComponentGroupSizes(components)
36	    .map(alikeComponentGroupBasePremium)
37	    .reduce((sum, premium) => sum + premium, 0);
38	}
39	
40	function mainItemsBasePremium(mainItems: Item[]): number {
41	  return mainItems
42	    .map(itemBasePremium)
43	    .reduce((sum, premium) => sum + premium, 0);
44	}
45	
46	function policyBasePremium(items: Item[]): number {
47	  return (
48	    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
49	    componentsBasePremium(items.filter(isComponent))
50	  );
51	}
52	
53	interface ItemRisk {
54	  applies: (item: Item) => boolean;
55	  surchargeRate: number;
56	}
57	
58	const isCursed = (item: Item): boolean => item.cursed === true;
59	
60	const isHighlyEnchanted = (item: Item): boolean =>
61	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
62	
63	const ITEM_RISKS: ItemRisk[] = [
64	  { applies: isCursed, surchargeRate: CURSE_SURCHARGE_RATE },
65	  { applies: isHighlyEnchanted, surchargeRate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
66	];
67	
68	function itemRiskSurcharge(item: Item): number {
69	  return ITEM_RISKS.filter((risk) => risk.applies(item))
70	    .map((risk) => itemBasePremium(item) * risk.surchargeRate)
71	    .reduce((sum, surcharge) => sum + surcharge, 0);
72	}
73	
74	function itemRiskSurcharges(items: Item[]): number {
75	  return items
76	    .map(itemRiskSurcharge)
77	    .reduce((sum, surcharge) => sum + surcharge, 0);
78	}
79	
80	// Every item in a quote is insured for the first time, so the initial assessment
81	// surcharge applies to every quote -- it does not depend on the customer's history.
82	function initialAssessmentOnEveryQuote(basePremium: number): number {
83	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
84	}
85	
86	interface CustomerStanding {
87	  yearsWithMHPCO: number;
88	  previousContracts: number;
89	}
90	
91	interface CustomerStandingDiscount {
92	  earnedBy: (standing: CustomerStanding) => boolean;
93	  discountRate: number;
94	}
95	
96	const isLongStanding = (standing: CustomerStanding): boolean =>
97	  standing.yearsWithMHPCO >= LOYALTY_YEARS;
98	
99	const isFollowUpContract = (standing: CustomerStanding): boolean =>
100	  standing.previousContracts > 0;
101	
102	const CUSTOMER_STANDING_DISCOUNTS: CustomerStandingDiscount[] = [
103	  { earnedBy: isLongStanding, discountRate: LOYALTY_DISCOUNT_RATE },
104	  { earnedBy: isFollowUpContract, discountRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
105	];
106	
107	function customerStandingDiscounts(
108	  standing: CustomerStanding,
109	  basePremium: number,
110	): number {
111	  return CUSTOMER_STANDING_DISCOUNTS.filter((discount) =>
112	    discount.earnedBy(standing),
113	  )
114	    .map((discount) => basePremium * discount.discountRate)
115	    .reduce((sum, amount) => sum + amount, 0);
116	}
117	
118	function policyWideModifiers(
119	  standing: CustomerStanding,
120	  basePremium: number,
121	): number {
122	  return (
123	    initialAssessmentOnEveryQuote(basePremium) -
124	    customerStandingDiscounts(standing, basePremium)
125	  );
126	}
127	
128	function premiumRoundedInMhpcosFavor(premium: number): number {
129	  return Math.ceil(premium);
130	}
131	
132	export function quote(
133	  customer: Customer,
134	  items: Item[],
135	  previousContracts: number,
136	): number {
137	  const basePremium = policyBasePremium(items);
138	  const standing = { ...customer, previousContracts };
139	  const premium =
140	    basePremium +
141	    itemRiskSurcharges(items) +
142	    policyWideModifiers(standing, basePremium) +
143	    PROCESSING_FEE;
144	  return premiumRoundedInMhpcosFavor(premium);
145	}
