  cause: string;
  damages: Damage[];
}

export interface Policy {
  insuredItems: Item[];
  // How much the MHPCO may still pay out over this policy's lifetime.
  remainingCap: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
